"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["84483"],{62948(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_divulgacao.campo_nao_permitido","status":422,"titulo":"Campo fora do vocabul\xe1rio de divulga\xe7\xe3o p\xfablica"},"descricao":{"codigo":"uniplus.selecao.configuracao_divulgacao.campo_nao_permitido","requisitos":[],"oQueAconteceu":["Os campos que podem ser divulgados nas listas p\xfablicas de resultado formam um vocabul\xe1rio\\nfechado: `NUMERO_INSCRICAO`, `NOME_ABREVIADO` e `NOME`. Um ou mais itens de `camposPublicos` n\xe3o\\nest\xe3o nele, ou s\xe3o nulos. A mensagem n\xe3o repete o valor recusado.","A recusa acontece depois de o sistema encontrar o processo e aceitar a precondi\xe7\xe3o de edi\xe7\xe3o, e \xe9\\nconferida sobre a lista como foi enviada. Ela vem junto das demais viola\xe7\xf5es do mesmo pedido, no\\narray `errors[]`, na ordem em que as regras s\xe3o conferidas. Podem aparecer junto dela\\n[`numero_inscricao_obrigatorio`](/erros/uniplus.selecao.configuracao_divulgacao.numero_inscricao_obrigatorio)\\n(quando a lista n\xe3o tem o n\xfamero de inscri\xe7\xe3o),\\n[`formas_de_identificacao_excludentes`](/erros/uniplus.selecao.configuracao_divulgacao.formas_de_identificacao_excludentes)\\ne as recusas da justificativa. A lista vazia \xe9 outra causa\\n([`campos_publicos_vazio`](/erros/uniplus.selecao.configuracao_divulgacao.campos_publicos_vazio)) e n\xe3o\\nvem junto desta.","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz um campo fora do\\nvocabul\xe1rio, porque a defini\xe7\xe3o o recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o \xfanica,\\nsem a lista `errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Deixe em `camposPublicos` apenas itens do vocabul\xe1rio: `NUMERO_INSCRICAO`, `NOME_ABREVIADO` ou\\n`NOME`, com a grafia exata, em mai\xfasculas. A API tamb\xe9m publica a lista dos campos de divulga\xe7\xe3o\\nem consulta de vocabul\xe1rio. Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija\\ntodas antes de reenviar.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir a divulga\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o da divulga\xe7\xe3o p\xfablica do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Defini\xe7\xe3o de etapas e do cronograma das fases de processo publicado, quando declaram atos","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao divulgacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);